const select = document.getElementById("choosers");

select.addEventListener("change", () => {
  const option = select.options[select.selectedIndex];
  const group = option.parentElement;
  const key = group.label + ":" + option.value;

  if (key === "Download as:plainzip") renameToZip();
});

function renameToZip() {
  if (!lastFile) return;

  const blob = lastFile.slice(0, lastFile.size, lastFile.type);
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);

  const base = lastFile.name.replace(/\.(scratchjr|sjr|jrs)$/i, "");
  a.download = base + ".zip";

  a.click();
}